    /// The theme ids (spec §4.16), in Settings order; the first is the default.
    public static let themeIDs: [String] = ["study", "gallery", "rain", "grove", "dusk"]

    /// The sheet the reader puts in `<style id="ss-theme">` for theme `id` (spec §4.16): the head's colour selectors,
    /// in the head's order, holding only the variables that differ from the default theme's, so it goes after the head
    /// and overrides nothing else. Empty for the default theme and for an id no theme has.
    public static func themeSheet(_ id: String) -> String {
        switch id {
        case "gallery": return gallerySheet
        case "rain": return rainSheet
        case "grove": return groveSheet
        case "dusk": return duskSheet
        default: return ""
        }
    }

